package com.fincore.fincore.account; import java.util.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; public interface AccountRepository extends JpaRepository<Account,Long>{List<Account> findAllByUserIdOrderByCreatedAtDesc(Long userId); Optional<Account> findByIdAndUserId(Long id,Long userId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select a from Account a where a.id=:id") Optional<Account> findByIdForUpdate(@Param("id") Long id);}
